P.entries["item:99-year-old-port"] = {n="Porto di 99 Anni",s="Il Porto di 99 Anni è una bottiglia rarissima di liquore d'annata spedita da Baia del Bottino come regalo personale per Sparachiodi. Dopo un incidente con il carico sui moli di Porto Paranco, è stata sottratta da un folle di nome Magglish il Pazzo, che è fuggito nelle gallerie tortuose fuori dalla Caverna dei Lamenti.",h="Il Porto di 99 Anni è una bottiglia rarissima di liquore d'annata spedita da Baia del Bottino come regalo...",kw={"porto di 99 anni","chiavecurva","sparachiodi","magglish il pazzo","porto","porto paranco","granbottino","caverna dei lamenti"},ang={["class:Rogue"]="Magglish il Pazzo si affida a una furtività da dilettante per nascondersi nel buio fuori dalla Caverna dei Lamenti, ma un ladro esperto può stanarlo facilmente dalle ombre."},sec={{t="Un carico prezioso finito a terra",b="Trasportare merci preziose attraverso il Grande Mare comporta sempre dei rischi, ma l'Operatore della Gru Chiavecurva ha peggiorato di molto le cose durante un normale scarico mattutino a Porto Paranco. Nel tentativo di smaltire un carico enorme arrivato da Baia del Bottino, il goblin ha sovraccaricato la sua gru, facendo precipitare una montagna di casse sui moli. Nel caos, l'eccentrico del paese, un personaggio molesto noto come Magglish il Pazzo, ha afferrato una bottiglia straordinariamente invecchiata di Porto di 99 Anni ed è scappato verso le colline, in direzione della Caverna dei Lamenti."},{t="Un'annata diplomatica",b="Il porto rubato non era un liquore qualunque: era stato inviato dal Barone Granbottino dei Predoni Acquanera come prestigioso dono diplomatico per Sparachiodi, l'ingegnere capo e signore di Porto Paranco. La perdita di un carico tanto prezioso minacciava il sostentamento di Chiavecurva e aumentava le tensioni con il capo del porto. Seguito fino alle buie grotte esterne delle caverne, il ladro sfuggente si nasconde nell'ombra con il prezioso bottino ancora sigillato, costringendo gli scaricatori ad assoldare mercenari esterni per recuperarlo prima che Sparachiodi scopra il pasticcio."}},faq={{q="A chi era destinato in origine il Porto di 99 Anni?",a="La bottiglia era stata inviata dal Barone Granbottino, signore di Baia del Bottino, come prezioso regalo personale per Sparachiodi, il capo di Porto Paranco.",al={"per chi è il porto","chi riceve il porto","regalo per sparachiodi"}},{q="Come è finito il porto nelle mani di Magglish il Pazzo?",a="L'Operatore della Gru Chiavecurva ha tentato di scaricare più merce di quanta il suo macchinario potesse sopportare, rovesciando casse su tutti i moli di Porto Paranco. Magglish il Pazzo ha approfittato del caos per afferrare la bottiglia d'annata e fuggire.",al={"come è stato rubato","chi ha rubato il porto","incidente al molo"}},{q="Dove ha portato la bottiglia Magglish il Pazzo?",a="Magglish è fuggito verso l'interno attraverso le Savane e si è rintanato nelle anticamere rocciose e nelle gallerie esterne che portano alla Caverna dei Lamenti.",al={"dov'è magglish il pazzo","dov'è nascosto il porto","posizione del porto"}},{q="Perché Chiavecurva non ha recuperato il porto da solo?",a="Chiavecurva ha inseguito il ladro fino alla soglia della Caverna dei Lamenti, ma, terrorizzato dalle bestie e dai druidi corrotti che infestano le grotte, si è rifiutato di entrare.",al={"perché chiavecurva non lo insegue","operatore della gru codardo"}}},fx={["5b0242c9"]={q="Che cos'è il Porto di 99 Anni?",a="È una bottiglia di vino liquoroso eccezionalmente rara e invecchiata, spedita fin da Baia del Bottino. Inviata come prestigioso dono personale dal Barone Granbottino a Sparachiodi, ingegnere capo e guida di Porto Paranco, quest'annata è un inestimabile segno di stima tra potenti baroni del commercio goblin.",al={"che cos'è il porto di 99 anni","porto di 99 anni","bottiglia di porto"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
