P.entries["item:arnak-s-hoof"] = {n="Zoccolo di Arnak",s="Lo Zoccolo di Arnak è la macabra prova della morte del criminale Arnak Totem Truce. Braccato sulle rupi del Pinnacolo Nubenera, Arnak era stato condannato a morte dai difensori del Presidio di Ventolibero dopo aver ucciso un altro tauren e averne rapito la sorella.",h="Lo Zoccolo di Arnak è la macabra prova della morte del criminale Arnak Totem Truce.",kw={"arnak","arnak totem truce","zoccolo di arnak","guardiacolli corno lungo","pinnacolo nubenera","presidio di ventolibero","lakota soffia vento","millepicchi"},ang={["faction:Horde"]="Eliminare Arnak consolida l'autorità del Presidio di Ventolibero a Millepicchi e indebolisce l'influenza infida dei Totem Truce che minaccia le vie di rifornimento dell'Orda.",["race:Tauren"]="Per i tauren delle pianure, prendere lo zoccolo di Arnak è un atto di giustizia tribale contro un rinnegato la cui condotta omicida ha portato disonore e spargimento di sangue a Millepicchi."},sec={{t="Una taglia su un reietto",b="Arnak Totem Truce divenne famigerato in tutta Millepicchi come un fuorilegge la cui brutalità superava persino i confini delle controverse politiche tra i clan tauren. Dopo che ebbe ucciso un altro tauren e rapito la sorella della vittima, Lakota Soffia Vento, fu emessa una taglia ufficiale per la sua morte. Arnak si rifugiò sulle alture del Pinnacolo Nubenera, circondato da guardie Totem Truce. Ucciderlo e prenderne lo zoccolo mozzato è la conferma innegabile per il Guardiacolli Corno Lungo, al Presidio di Ventolibero, che l'assassino ha finalmente pagato per i suoi crimini."}},faq={{q="A che cosa serve lo Zoccolo di Arnak?",a="Lo Zoccolo di Arnak è la prova materiale della morte del fuorilegge Arnak Totem Truce. Si consegna al Guardiacolli Corno Lungo al Presidio di Ventolibero per completare la taglia e riscuotere la ricompensa promessa.",al={"consegna dello zoccolo di arnak","cosa faccio con lo zoccolo di arnak","chi vuole lo zoccolo di arnak"}},{q="Chi era Arnak Totem Truce?",a="Arnak era un rinnegato Totem Truce ricercato per omicidio e rapimento. Uccise un membro di una tribù tauren e tenne prigioniera la sorella della vittima, Lakota Soffia Vento, sulle rupi del Pinnacolo Nubenera.",al={"chi è arnak","storia di arnak totem truce","perché arnak è ricercato"}},{q="Dove si trova Arnak Totem Truce?",a="Arnak si trova sulle scogliere del Pinnacolo Nubenera, nel nord di Millepicchi, raggiungibili tramite ponti di corda vicino alle rupi che portano ai Sotterranei di Lamaspina. Tiene la sua prigioniera, Lakota Soffia Vento, sulla stessa rupe.",al={"posizione di arnak totem truce","dov'è arnak","come trovare arnak"}}},fx={["8804d903"]={q="Che cos'è lo Zoccolo di Arnak?",a="Questo zoccolo mozzato è la prova inconfutabile che il tauren fuorilegge Arnak Totem Truce è stato ucciso. Staccato direttamente dal suo corpo in cima alle mese battute dal vento di Millepicchi, viene riportato al Presidio di Ventolibero per confermare che la giustizia ha finalmente raggiunto il rinnegato.",al={"zoccolo di arnak","che zoccolo è questo","lo zoccolo di arnak"}},a4f2e55c={q="Da dove viene lo Zoccolo di Arnak?",a="Si prende da Arnak Totem Truce, un tauren rinnegato che si nasconde sulle scogliere vicino al Pinnacolo Nubenera. Non è un oggetto forgiato o lavorato, ma un trofeo conquistato dopo averlo affrontato e ucciso nel suo covo affacciato sui canyon.",al={"dove si ottiene lo zoccolo di arnak","origine dello zoccolo di arnak","provenienza dello zoccolo di arnak"}},ffececdb={q="Perché qualcuno vuole lo Zoccolo di Arnak?",a="Il Guardiacolli Corno Lungo, al Presidio di Ventolibero, ha affisso una taglia che richiede la prova della morte di Arnak. Arnak ha commesso crimini atroci: ha ucciso un tauren innocente e ne ha rapito la sorella, Lakota Soffia Vento. Consegnare il suo zoccolo salda la taglia e vale la gratitudine e il denaro dei protettori del Presidio di Ventolibero.",al={"chi vuole lo zoccolo di arnak","perché consegnare lo zoccolo di arnak","perché volere lo zoccolo di arnak"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
