P.entries["item:bag-of-empty-ooze-containers"] = {n="Sacca di Contenitori per Melme Vuoti",s="A Forgiardente, Laris Perdiruote fornisce barattoli vuoti per il suo studio sulle melme di Azeroth. Servono a contenere melma pulita raccolta nelle terre selvagge.",h="A Forgiardente, Laris Perdiruote fornisce barattoli vuoti per il suo studio sulle melme di Azeroth.",kw={"sacca di contenitori per melme vuoti","contenitore di campioni puri vuoto","forgiardente","laris perdiruote","contenitori per melme","contenitore di campioni puri","melma"},ang={["faction:Alliance"]="Per chi viaggia con l'Alleanza, è l'occasione di aiutare Laris Perdiruote nelle sue ricerche ecologiche a Forgiardente, portandogli campioni da luoghi selvaggi come il Cratere di Un'Goro.",["race:Gnome"]="Per chi è gnomo, questi barattoli robusti e resistenti agli agenti chimici sono un esempio di ingegno: permettono ai ricercatori di trasportare in sicurezza campioni di fauna pericolosi e corrosivi."},sec={{t="Attrezzatura per la ricerca sul campo",b="Laris Perdiruote studia la strana biologia delle melme di Azeroth. Ha scoperto che assorbono rapidamente la corruzione che le circonda, compresi i residui contaminati del Vilbosco. Così ha commissionato barattoli robusti, capaci di contenere esemplari acidi senza danneggiarli. La sacca contiene abbastanza barattoli per raccogliere melma pulita nelle regioni selvagge, soprattutto nel Cratere di Un'Goro, dove antiche melme glutinose vivono lontano dalla contaminazione demoniaca."}},faq={{q="Che cosa contiene la Sacca di Contenitori per Melme Vuoti?",a="La sacca contiene dieci Contenitori di Campioni Puri Vuoti. Il loro vetro può contenere melma caustica senza danneggiare o contaminare il campione.",al={"cosa c'è nella sacca","contenuto della sacca","contenuto dei contenitori per melme"}},{q="Chi ha fornito questi contenitori?",a="Li fornisce Laris Perdiruote, un ricercatore gnomo del Salone degli Esploratori di Forgiardente, che studia come le melme si adattano all'ambiente.",al={"chi dà la sacca per melme","sacca di laris perdiruote","chi dà la sacca di contenitori per melme vuoti"}},{q="Che tipo di melme devono raccogliere questi barattoli?",a="I barattoli sono destinati a melma pura e incontaminata. Puoi raccogliere melma intatta dalle melme glutinose del Cratere di Un'Goro, a differenza degli esemplari corrotti del Vilbosco.",al={"quale melma va nei barattoli","obiettivo del contenitore di campioni puri","dove riempire i barattoli"}},{q="Perché Laris ha bisogno di campioni di melma puri?",a="Laris ha bisogno di melma pura per studiare come le melme assorbono le qualità del loro ambiente. Così può confrontare un esemplare incontaminato con le melme inquinate delle regioni corrotte.",al={"perché raccogliere melma pura","obiettivo della ricerca di perdiruote","perché melme pure"}}},fx={["9a2213f5"]={q="Che cos'è la Sacca di Contenitori per Melme Vuoti?",a="Questa sacca è un kit di attrezzatura specializzata da campo, che ti consegna Laris Perdiruote a Forgiardente. Contiene dieci barattoli per campioni vuoti, pensati per conservare e trasportare in sicurezza fino alla sua officina esemplari instabili di melma, senza perdite e senza contaminarne il contenuto.",al={"sacca di contenitori per melme vuoti","che cosa sono i contenitori per melme","sacca per melme di laris"}}},fp="28,142,24.407.0,48.119.0,30.148.0,51.161.0,38.165.0"}
