P.entries["item:barrel-of-barleybrew-scalder"] = {n="Barile di Ustionante dei Maltorzo",s="A Kharanos, Marleth Maltorzo manda una botte di Ustionante verso la Distilleria Birratuono. Vuole dimostrare che le sue birre possono rivaleggiare con quelle dei Birratuono, i suoi principali concorrenti.",h="A Kharanos, Marleth Maltorzo manda una botte di Ustionante verso la Distilleria Birratuono.",kw={"birra","maltorzo","distilleria","dun morogh","kharanos","marleth","ustionante","birratuono"},ang={["class:Rogue"]="Chi è ladro sa distrarre una guardia della cantina e infilare un pesante carico di contrabbando in un deposito sorvegliato. Qui puoi assaggiare il sotterfugio nanico con poco in gioco.",["race:Dwarf"]="Per chi appartiene al popolo dei nani, fare la birra è al tempo stesso un'arte e uno sport sanguinario. A Dun Morogh, le rivalità sulle ricette arrivano fin dentro la cantina."},sec={{t="Un'aspra faida a Dun Morogh",b="I Birratuono e i Maltorzo si contendono ferocemente il primato della birra a Dun Morogh. I Birratuono sono famosi per la loro affollata distilleria a Kharanos, ma Marleth Maltorzo non vuole restare nella loro ombra. Così produce l'infuocata Ustionante per dimostrare che le sue ricette valgono quanto le loro. Spera che chi la assaggia capisca che i Birratuono non hanno il monopolio delle buone bevande naniche."},{t="Sotterfugi in cantina",b="Il barile è destinato alle cantine sotto la Distilleria Birratuono, dove prenderà il posto di una botte di Birra del Tuono, la preferita del posto. L'orgoglio ferito ha fatto nascere uno scherzo, non un avvelenamento o un sabotaggio: la prossima birra servita al piano di sopra sarà, in segreto, la potente Ustionante dei Maltorzo."}},faq={{q="Che cosa contiene il Barile di Ustionante dei Maltorzo?",a="Il barile contiene l'Ustionante tipica di Marleth Maltorzo, una potente birra nanica creata per rivaleggiare con le celebri ricette della famiglia Birratuono.",al={"contenuto dell'ustionante dei maltorzo","che tipo di birra","cos'è l'ustionante"}},{q="Perché Marleth vuole che questo barile venga scambiato?",a="Marleth ammette che i Birratuono fanno buone bevande, ma vuole che imparino l'umiltà. Spera che i clienti della cantina assaggino la sua birra senza saperlo e trovino l'arte dei Maltorzo altrettanto buona, se non migliore.",al={"perché scambiare i barili","motivo della rivalità","perché marleth infila la sua birra"}},{q="Dove va portato questo barile?",a="Il barile va nella cantina sotto la Distilleria Birratuono di Kharanos, dove prende il posto, sulle rastrelliere, di una botte di Birra del Tuono che sta per essere spillata.",al={"dove metto il barile","posizione del barile di ustionante","cantina della distilleria"}},{q="La birra deve fare del male a qualcuno?",a="No. È una birra nanica forte, creata per rivaleggiare con quella dei Birratuono. La rivalità tra le due famiglie è feroce, ma nasce dall'orgoglio professionale, non dalla cattiveria.",al={"l'ustionante è avvelenata","è veleno","farà male a qualcuno"}}},fx={["9f414f7e"]={q="Che cos'è il Barile di Ustionante dei Maltorzo?",a="È un barile di birra forte prodotta da Marleth Maltorzo. Non è destinato al commercio ordinario: questo particolare barile è lo strumento di una rivalità tra birrai e va sostituito di nascosto alle scorte di un concorrente, per conquistare bevitori ignari.",al={"che cos'è l'ustionante dei maltorzo","barile di ustionante dei maltorzo","il barile di ustionante dei maltorzo"}},["00d1bcdd"]={q="Da dove viene il Barile di Ustionante dei Maltorzo e chi l'ha prodotto?",a="Il barile è stato prodotto e fornito da Marleth Maltorzo. Fiero dell'arte della sua famiglia, Marleth ha messo a punto la ricetta per dimostrare che i Maltorzo possono eguagliare o superare la fama della famiglia rivale dei Birratuono.",al={"chi ha prodotto l'ustionante dei maltorzo","da dove viene l'ustionante dei maltorzo","origine dell'ustionante dei maltorzo"}}},fp="28,171,27.356.0,24.282.1,48.132.0,42.212.0,26.154.0,33.153.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Barile di Scura Brillante",s="A Dun Morogh, un barile di Scura Brillante è destinato alle sentinelle di montagna. Rejold Maltorzo manda la sua birra sperimentale sui passi d'alta quota, dove chi la beve giura che renda la vista più brillante.",h="A Dun Morogh, un barile di Scura Brillante è destinato alle sentinelle di montagna.",kw={"barile di scura brillante","dun morogh","birra nanica","loch modan","montanaro maltorzo","rejold maltorzo","scura brillante"},ang={["profession:Cooking"]="Chi cucina sa che i birrai nanici sperimentano con robusti ingredienti di montagna e fermentazioni potenti, per produrre birre adatte al clima pungente.",["race:Dwarf"]="Per chi appartiene al popolo dei nani, fare la birra è un pilastro della società di Forgiardente. Portare una birra appena perfezionata a un parente di guardia è un'onorevole tradizione di montagna."},sec={{t="L'orgoglio di un birraio",b="Rejold Maltorzo ha prodotto la Scura Brillante con ingredienti raccolti in tutta Dun Morogh. La ricetta è l'ultima creazione della famiglia Maltorzo, i cui birrai nanici competono per produrre birre abbastanza corroboranti da resistere al gelo delle montagne. Rejold l'ha creata per scaldare lo stomaco e affinare i sensi di chi è di stanza tra i venti."},{t="Rifornimenti per la guardia",b="Il barile è destinato al Montanaro Wellart Maltorzo, alla torre meridionale sul passo che porta a Loch Modan. I montanari lassù sopportano il freddo e lunghi turni di guardia tra le schermaglie con trogg e animali selvatici. Una botte della birra di famiglia porta un sapore di casa, e la sua forza può far sentire una sentinella stanca capace di vederci chiaro anche al buio."}},faq={{q="Che cosa c'è nel Barile di Scura Brillante?",a="Il barile contiene la Scura Brillante, una birra nanica sperimentale prodotta da Rejold Maltorzo. Chi la beve dice che la sua potente scossa renda la vista più brillante.",al={"cos'è la scura brillante","che tipo di birra è","bevanda scura brillante"}},{q="Chi ha prodotto questo barile di birra scura?",a="La birra l'ha prodotta Rejold Maltorzo. Appartiene alla famiglia Maltorzo di Dun Morogh e ha passato del tempo a perfezionare la ricetta per far colpo sui suoi parenti.",al={"chi ha prodotto la scura brillante","birraio della scura brillante","rejold maltorzo"}},{q="A chi è destinato questo barile?",a="Il barile è destinato al fratello di Rejold, il Montanaro Wellart Maltorzo, che sorveglia la torre meridionale sulla strada per Loch Modan.",al={"chi riceve il barile","dove va la scura","wellart maltorzo"}},{q="Che effetto ha la Scura Brillante su chi la beve?",a="La Scura Brillante dà a chi la beve una potente ebbrezza e la sensazione di poter vedere nel buio più totale. La sua forza la rende popolare tra i montanari sempre all'erta.",al={"effetto della scura brillante","fa vedere al buio","cosa fa la scura brillante"}}},fp="23,184,16.304.0,22.318.0,39.141.0,30.142.0,29.136.0,61.155.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Barile di Birra del Tuono",s="A Kharanos, la Distilleria Birratuono ha perso un barile di Birra del Tuono. L'Ustionante dei Maltorzo di Marleth doveva prenderne il posto, trasformando una faida tra birrai in un sabotaggio.",h="A Kharanos, la Distilleria Birratuono ha perso un barile di Birra del Tuono.",kw={"barile di birra del tuono","borgo luppolo","dun morogh","kharanos","marleth maltorzo","birra del tuono","birratuono"},ang={["class:Rogue"]="Chi è ladro sa quanta abilità serva per intrufolarsi in una cantina sorvegliata e scambiare pesanti barili di birra senza dare l'allarme.",["race:Dwarf"]="Per chi appartiene al popolo dei nani, fare la birra pesa sia negli affari sia nella politica. Scambiare la preziosa botte di un clan rivale nella sua stessa cantina è un insulto sfrontato."},sec={{t="Uno scambio amaro",b="I Birratuono di Kharanos e i Maltorzo di Borgo Luppolo sono acerrimi rivali. Marleth Maltorzo ha cercato di infilare un barile della sua Ustionante dei Maltorzo nella cantina dei Birratuono, sperando che i loro clienti scegliessero la sua birra. Il barile di Birra del Tuono è stato preso durante lo scambio, prova che il colpo è riuscito nonostante le guardie locali."}},faq={{q="Che cosa contiene questo barile?",a="Il barile contiene la Birra del Tuono, la famosa birra scura prodotta dalla famiglia Birratuono a Kharanos. In tutta Dun Morogh è nota come una potente birra nanica.",al={"contenuto della birra del tuono","cos'è la birra del tuono"}},{q="Da dove viene questo barile?",a="Il barile viene dal magazzino della cantina della Distilleria di Kharanos. È stato preso durante la consegna clandestina della birra rivale di Marleth.",al={"dove si ottiene","posizione della birra del tuono"}},{q="Chi vuole questo barile?",a="Il barile lo vuole Marleth Maltorzo. Si trova a Borgo Luppolo, più a ovest, e lo aspetta come prova che la sua Ustionante è stata piazzata tra i barili dei Birratuono.",al={"a chi porto la birra del tuono","missione di marleth maltorzo"}},{q="Perché il barile è stato preso?",a="Marleth voleva la prova che qualcuno fosse entrato nella cantina dei Birratuono, avesse superato la guardia della distilleria e sabotato le scorte dei suoi rivali.",al={"perché rubare la birra del tuono","storia della rivalità"}}},fp="21,170,14.341.0,27.148.0,32.132.0,22.160.0,25.134.0"}
