P.entries["item:bingles-blastencapper"] = {n="Scoppiabarile di Bingles",s="I trogg hanno lo Scoppiabarile di Bingles da quando il suo girocottero è precipitato nel lago. Senza di esso, i piani di Bingles per aiutare la liberazione di Gnomeregan sono a rischio.",h="I trogg hanno lo Scoppiabarile di Bingles da quando il suo girocottero è precipitato nel lago.",kw={"bingles","scoppiabarile","scoppiamicce","esplosivi","gnomeregan","girocottero","loch modan","trogg"},ang={["profession:Engineering"]="Lo Scoppiabarile mostra l'estro dell'ingegneria gnomica: complesso ed esplosivo, può essere devastante quando colpisce dall'alto.",["race:Gnome"]="Ogni attrezzo e ogni munizione contano mentre gli gnomi lottano per riconquistare Gnomeregan. Recuperare l'esplosivo di Bingles potrebbe permettere all'ingegno aereo gnomico di contrattaccare gli invasori trogg."},sec={{t="Un'invenzione instabile",b="Bingles Scoppiamicce costruì lo Scoppiabarile per colpire dall'alto i trogg e gli gnomi contaminati che hanno invaso Gnomeregan. Un guasto meccanico fece precipitare il suo girocottero nel lago, ma Bingles sopravvisse. I trogg delle isole settentrionali saccheggiarono il relitto e portarono l'arma instabile nei loro accampamenti."},{t="Supporto aereo per Gnomeregan",b="A Bingles serve lo Scoppiabarile per aiutare a riconquistare Gnomeregan. Gli gnomi esuli si preparano a riprendersi la loro casa radioattiva, e lui conta sul suo girocottero e sulle sue munizioni speciali per l'assalto aereo. In mano ai trogg, l'esplosivo potrebbe causare per errore una catastrofe a Loch Modan. Recuperarlo preserverebbe un'arma preziosa per la resistenza gnomica."}},faq={{q="Che cos'è lo Scoppiabarile di Bingles?",a="Bingles Scoppiamicce ha creato lo Scoppiabarile per colpire dall'alto i trogg e gli gnomi contaminati che occupano Gnomeregan.",al={"cos'è lo scoppiabarile","scoppiabarile","esplosivo di bingles"}},{q="Come è finito lo Scoppiabarile nel lago?",a="Bingles è precipitato con il suo girocottero nel lago. I trogg delle isole vicine hanno saccheggiato il relitto e portato via i suoi attrezzi, compreso l'esplosivo.",al={"perché è nel lago","come l'ha perso bingles","schianto"}},{q="Chi ha attualmente lo Scoppiabarile?",a="I trogg delle isole settentrionali del lago hanno preso lo Scoppiabarile dal relitto e lo sorvegliano nel loro accampamento.",al={"chi ha rubato lo scoppiabarile","chi ce l'ha","trogg"}},{q="Perché Bingles ha bisogno che lo Scoppiabarile gli venga restituito?",a="A Bingles servono lo Scoppiabarile e i suoi attrezzi per riparare il girocottero e lanciare un assalto aereo a sostegno della riconquista di Gnomeregan.",al={"perché rivuole lo scoppiabarile","perché lo scoppiabarile è importante","per gnomeregan"}}},fp="22,148,20.300.0,26.361.0,31.120.0,45.144.0,36.110.0,49.141.0"}
P.entries["item:bingles-hammer"] = {n="Martello di Bingles",s="Sul luogo del suo schianto a Loch Modan, Bingles Scoppiamicce ha bisogno di riavere dai trogg il Martello di Bingles. Con l'attrezzatura recuperata, potrà riparare la sua macchina volante e aiutare a liberare Gnomeregan.",h="Sul luogo del suo schianto a Loch Modan, Bingles Scoppiamicce ha bisogno di riavere dai trogg il Martello di...",kw={"bingles","scoppiamicce","gnomeregan","martello","loch modan","secchio degli attrezzi","trogg"},ang={["profession:Engineering"]="Chi pratica l'ingegneria sa che un buon martello di fattura gnomica è difficile da sostituire. A Bingles ne serve uno per ricostruire il suo girocottero sperimentale nelle terre selvagge.",["race:Gnome"]="Per chi è gnomo, ogni attrezzo recuperato avvicina l'assalto aereo per liberare la tua casa ancestrale."},sec={{t="La cassetta degli attrezzi di un aviatore bloccato",b="I trogg hanno saccheggiato il luogo dello schianto di Bingles Scoppiamicce, sulle isole d'acqua dolce, portando via il suo martello e i suoi esplosivi ad alto potenziale. Il martello serve per riparare la fusoliera ammaccata e regolare le parti meccaniche del girocottero. Senza la sua attrezzatura, Bingles non può effettuare voli di supporto per le forze gnomiche che lottano per riconquistare Gnomeregan."}},faq={{q="Dove si trova il Martello di Bingles?",a="Il Martello di Bingles si trova in uno dei Secchi degli Attrezzi di Bingles sparsi sulle isole infestate dai trogg nella parte settentrionale del lago.",al={"posizione del martello","dov'è il martello di bingles","come trovare il martello"}},{q="A chi appartiene questo martello?",a="Il martello appartiene a Bingles Scoppiamicce, un ingegnere e pilota gnomo. La sua macchina volante si è schiantata sulle rive di Loch Modan.",al={"di chi è il martello","proprietario del martello di bingles"}},{q="Perché questo attrezzo è così importante per Bingles?",a="A Bingles serve l'intera serie di attrezzi per ricostruire il girocottero abbattuto. Intende usarlo contro i trogg e gli gnomi contaminati che occupano Gnomeregan.",al={"perché serve il martello","uso del martello di bingles"}},{q="Chi ha rubato il Martello di Bingles?",a="I trogg che vivono sulle isole del lago hanno saccheggiato il luogo dello schianto, portando via i secchi degli attrezzi di Bingles e i suoi esplosivi Scoppiabarile personalizzati.",al={"chi ha preso il martello","trogg ladri"}}},fp="15,181,28.330.0,35.122.0,31.131.0,41.146.0,26.124.0"}
P.entries["item:bingles-screwdriver"] = {n="Cacciavite di Bingles",s="Sulle isole settentrionali di Loch Modan, il Cacciavite di Bingles giace tra l'attrezzatura persa in uno schianto. I trogg l'hanno portato via insieme agli attrezzi del pilota Bingles Scoppiamicce.",h="Sulle isole settentrionali di Loch Modan, il Cacciavite di Bingles giace tra l'attrezzatura persa in uno...",kw={"bingles","scoppiamicce","girocottero","loch modan","cacciavite","secchio degli attrezzi","trogg"},ang={["profession:Engineering"]="Chi pratica l'ingegneria sa che un cacciavite di precisione è indispensabile per gli intricati rotori dei girocotteri e per i delicati meccanismi di innesco.",["race:Gnome"]="Per chi è gnomo, ogni attrezzo recuperato avvicina Bingles alla ricostruzione del suo velivolo e alla lotta contro i trogg e gli gnomi contaminati che hanno cacciato il tuo popolo da Gnomeregan."},sec={{t="La dotazione vitale di un pilota",b="Quando Bingles Scoppiamicce precipitò a Loch Modan, perse gli attrezzi necessari per riparare il suo girocottero. I trogg delle isole vicine portarono via i suoi secchi degli attrezzi, e il cacciavite era riposto in uno di questi. A Bingles serve per le regolazioni di precisione mentre ripara il velivolo e ne maneggia gli armamenti."},{t="I preparativi per la riconquista",b="Bingles lavora per liberare Gnomeregan dai trogg e dagli gnomi contaminati. Intende unire la sua abilità di volo alle instabili munizioni Scoppiabarile in un assalto aereo. Il cacciavite, la chiave meccanica e il martello lo aiuteranno a ricostruire il girocottero e a mantenere viva la controffensiva aerea."}},faq={{q="Dove si trova il Cacciavite di Bingles?",a="Dopo lo schianto di Bingles, i trogg hanno sparso i suoi Secchi degli Attrezzi sulle isole del nord di Loch Modan. Il cacciavite è in uno di questi.",al={"posizione del cacciavite","trovare il cacciavite di bingles","dov'è il cacciavite"}},{q="Perché il cacciavite è così importante per Bingles?",a="A Bingles servono il cacciavite e gli altri attrezzi per ricostruire il girocottero e preparare gli esplosivi per la campagna di riconquista di Gnomeregan.",al={"perché ne ha bisogno bingles","a cosa serve"}},{q="Chi ha rubato il cacciavite?",a="Dopo l'atterraggio di fortuna di Bingles, i trogg che vivono sulle isole di Loch Modan hanno preso i suoi secchi degli attrezzi e gli esplosivi Scoppiabarile.",al={"chi ha preso gli attrezzi","chi ha rubato gli attrezzi di bingles"}},{q="Quali altri attrezzi ha perso Bingles nello schianto?",a="Oltre al cacciavite, Bingles ha perso la chiave meccanica, il martello e la sua instabile scorta di esplosivi Scoppiabarile Scoppiamicce.",al={"altri attrezzi di bingles","cos'altro manca"}}},fx={f72526b7={q="Che cos'è il Cacciavite di Bingles?",a="Il Cacciavite di Bingles è un attrezzo da ingegnere appartenente a Bingles Scoppiamicce, uno gnomo aviatore rimasto bloccato a Loch Modan. Insieme alla chiave inglese e al martello, è uno degli strumenti indispensabili che portava a bordo del suo girocottero per fare manutenzione alla macchina volante e costruire ordigni per la resistenza degli gnomi.",al={"che cos'è il cacciavite di bingles","informazioni sul cacciavite di bingles","notizie sul cacciavite di bingles"}}},fp="20,164,19.293.0,29.275.0,36.137.0,47.137.0,45.122.0,47.123.0"}
P.entries["item:bingles-wrench"] = {n="Chiave Meccanica di Bingles",s="Nel lago, la Chiave Meccanica di Bingles è sparita insieme agli altri attrezzi del pilota. L'hanno presa i trogg dopo l'atterraggio di fortuna della macchina volante di Bingles Scoppiamicce.",h="Nel lago, la Chiave Meccanica di Bingles è sparita insieme agli altri attrezzi del pilota.",kw={"bingles","scoppiamicce","girocottero","loch modan","secchio degli attrezzi","trogg","chiave meccanica"},ang={["profession:Engineering"]="Chi pratica l'ingegneria sa che un artigiano senza la sua chiave meccanica personalizzata resta a terra, soprattutto con i trogg che frugano tra i rottami lì vicino.",["race:Gnome"]="Per chi è gnomo, ogni attrezzo recuperato avvicina la resistenza al giorno in cui porterà di nuovo la battaglia nelle sale irradiate di Gnomeregan."},sec={{t="Recupero sulle isole",b="Bingles Scoppiamicce è sopravvissuto quando il suo girocottero è precipitato nel lago. Poi i trogg hanno saccheggiato il luogo dello schianto, sulle piccole isole settentrionali. Hanno preso le sue provviste speciali e sparpagliato i suoi attrezzi in vari secchi nei loro accampamenti.\n\nLa Chiave Meccanica di Bingles è uno dei tre attrezzi manuali fondamentali, insieme ai suoi potenti esplosivi Scoppiabarile. Senza la chiave, Bingles non può riparare il girocottero abbattuto, e l'offensiva aerea che ha in programma a sostegno degli gnomi esuli che lottano per riconquistare Gnomeregan deve aspettare."}},faq={{q="A chi appartiene questa chiave meccanica?",a="La chiave meccanica appartiene a Bingles Scoppiamicce, un eccentrico pilota gnomo il cui girocottero è precipitato nel lago.",al={"chi è bingles","proprietario bingles","proprietario della chiave meccanica"}},{q="Perché la chiave meccanica è così importante per Bingles?",a="A Bingles servono i suoi attrezzi speciali per riparare la macchina volante danneggiata e armare il suo carico esplosivo per un assalto aereo contro i trogg e gli gnomi contaminati che occupano Gnomeregan.",al={"perché bingles ha bisogno della chiave meccanica","scopo della chiave meccanica","a cosa serve la chiave meccanica"}},{q="Dove è finita la chiave meccanica dopo lo schianto?",a="I trogg del posto hanno raccattato la chiave meccanica e l'hanno nascosta in uno dei secchi degli attrezzi rubati a Bingles, tra i loro accampamenti sulle isole settentrionali del lago.",al={"dov'è la chiave meccanica di bingles","posizione della chiave meccanica","trovare la chiave meccanica di bingles"}},{q="Che cos'altro è stato rubato insieme alla chiave meccanica?",a="I trogg hanno preso anche il Cacciavite di Bingles, il Martello di Bingles e i suoi esplosivi sperimentali Scoppiabarile Scoppiamicce.",al={"altre provviste","attrezzi mancanti","cos'altro hanno preso i trogg"}}},fp="15,145,22.497.0,31.109.0,42.182.0,44.141.0,43.120.0"}
P.entries["item:black-claw-stout"] = {n="Birra Scura Graffionero",s="Sotto Roccavento, Zardeth Graffionero prepara una bevanda per Ser Wishock. La birra gli arriva come una comune bevanda da taverna.",h="Sotto Roccavento, Zardeth Graffionero prepara una bevanda per Ser Wishock.",kw={"birra scura graffionero","sala dei supplicanti","ser wishock","veleno","agnello macellato","forte di roccavento","zardeth"},ang={["class:Warlock"]="Per la congrega segreta di stregoni di Roccavento, portare la birra è una semplice commissione: un nobile ficcanaso vuole chiudere il loro rifugio sotto l'Agnello Macellato.",["faction:Alliance"]="Portare la birra nel Forte di Roccavento avvicina gli stregoni dell'Agnello Macellato ai nobili della capitale."},sec={{t="Una bevanda tossica",b="Sotto le sale dell'Agnello Macellato, Zardeth Graffionero lavora lontano dagli occhi della guardia cittadina. Ser Wishock minaccia di continuo di chiudere la loro attività, mentre i suoi conti al bancone di sopra restano da pagare. Così Zardeth usa contro il nobile il suo debole per i liquori forti, nascondendo una dose letale in una comune bevanda da taverna."},{t="Un assassinio silenzioso",b="Nella Sala dei Supplicanti del Forte di Roccavento, Ser Wishock riceve la birra. L'orgoglio pomposo e la sete lo spingono ad accettare volentieri quella che scambia per l'offerta di un servitore premuroso, e la beve sul posto. Il veleno agisce quasi all'istante, mettendo a tacere uno dei critici politici più insistenti del culto proprio sotto il naso della Corte Reale."}},faq={{q="Che cos'è la Birra Scura Graffionero?",a="Zardeth Graffionero prepara la Birra Scura Graffionero per Ser Wishock nelle catacombe sotto l'Agnello Macellato, nel Quartiere dei Maghi di Roccavento.",al={"cos'è questa bevanda","storia della birra scura graffionero","birra avvelenata"}},{q="Chi è il bersaglio della birra?",a="Il bersaglio è Ser Wishock, un nobile prepotente della Sala dei Supplicanti che fa campagna per chiudere il rifugio degli stregoni mentre ci beve a credito.",al={"chi la beve","chi muore per la birra scura graffionero","bersaglio wishock"}},{q="Chi ha preparato la birra?",a="La birra la prepara Zardeth Graffionero nelle cripte sotto l'Agnello Macellato.",al={"creatore della birra scura graffionero","chi l'ha fatta","birra di zardeth"}},{q="Perché a Ser Wishock viene offerta la birra scura?",a="Zardeth manda la birra a Ser Wishock nella Sala dei Supplicanti, chiedendo al corriere di vedere quanto piace al nobile la sua birra speciale.",al={"wishock muore","effetto della birra scura graffionero"}}},fx={a6b6f1b7={q="Perché Zardeth vuole che tu consegni la Birra Scura Graffionero a Ser Wishock?",a="Ser Wishock è un nobile ipocrita, che passa le giornate a fare pressioni perché l'Agnello Macellato venga chiuso e le notti al piano di sopra a bere, accumulando un conto mai saldato. Per metterlo a tacere per sempre, Zardeth ha preparato questa birra speciale e letale: sfrutta il debole di Wishock per l'alcol e lo elimina con la scusa di offrirgli qualcosa di rinfrescante.",al={"perché consegnare la birra scura graffionero","perché dare la birra scura graffionero a wishock","zardeth wishock birra scura perché"}}},fp="16,133,15.332.1,19.338.1,25.143.0,31.151.0,21.85.0,38.128.1"}
