P.entries["item:cask-of-scalder"] = {n="Cassa di Ustionante",s="A Roccavento, una botte di Ustionante dei Maltorzo è destinata a una vecchia conoscenza. L'infuocata birra porta con sé un favore tra nani.",h="A Roccavento, una botte di Ustionante dei Maltorzo è destinata a una vecchia conoscenza.",kw={"birra","maltorzo","cassa di ustionante","distretto dei nani","furen barbalunga","costruttore di scudi","roccavento"},ang={["class:Warrior"]="Per chi è guerriero, portare una botte di buona birra a Furen Barbalunga è il modo di ottenere il suo celebre lavoro di forgia: un rito di passaggio essenziale per una protezione affidabile.",["race:Dwarf"]="Per chi appartiene al popolo dei nani, una botte fresca del miglior prodotto dei Maltorzo può sigillare un accordo o saldare un vecchio debito."},sec={{t="Un affare tra nani",b="I viaggiatori che hanno dimostrato il proprio valore nella prova di Rethban portano l'Ustionante dei Maltorzo a Furen Barbalunga, nel Distretto dei Nani di Roccavento. Furen è un artigiano costruttore di scudi e trova intollerabili i periodi di magra. La botte offre a Yorus Maltorzo il modo di riscuotere un vecchio favore e ottenere un lavoro nanico di alta qualità."}},faq={{q="Che cosa contiene la Cassa di Ustionante?",a="La botte contiene Ustionante dei Maltorzo, una birra infuocata prodotta dalla famiglia Maltorzo. I nani la apprezzano per il sapore deciso e per la sua forza riscaldante.",al={"che bevanda c'è dentro","birra ustionante","ustionante dei maltorzo"}},{q="A chi è destinata questa botte?",a="La botte è destinata a Furen Barbalunga, un esperto costruttore di scudi nanico del Distretto dei Nani di Roccavento.",al={"chi riceve la botte","dove la porto","destinatario dell'ustionante"}},{q="Perché questa botte viene consegnata a Furen Barbalunga?",a="Furen deve un favore a Yorus Maltorzo. La botte placa la sete di Furen durante quelli che lui chiama \"tempi di magra\" e lo convince a forgiare uno scudo robusto ed eccezionale per il corriere.",al={"perché furen vuole l'ustionante","favore del costruttore di scudi","scopo della botte"}}},fx={df3534f2={q="Che cos'è la Cassa di Ustionante?",a="La Cassa di Ustionante è un barilotto di legno pieno di Ustionante dei Maltorzo, una birra robusta prodotta dalla famiglia Maltorzo. Yorus Maltorzo te la affida come dono e presentazione per il suo amico nano di Roccavento, il costruttore di scudi Furen Barbalunga.",al={"che cos'è la cassa di ustionante","cassa di ustionante","che cos'è l'ustionante"}},["1fd358f8"]={q="Da dove viene la Cassa di Ustionante e chi l'ha prodotta?",a="La cassa ti viene data da Yorus Maltorzo, nelle Montagne Crestarossa, dopo il tuo trionfo nella prova di Rethban. Prodotta dal rinomato clan dei Maltorzo, questa birra inconfondibile viene tirata fuori come un favore di tutto rispetto, degno di procurarti uno scudo d'autore forgiato dai nani.",al={"chi ha prodotto la cassa di ustionante","origine della cassa di ustionante","da dove viene la cassa di ustionante"}}},fp="15,123,17.311.0,35.132.0,30.99.0,52.170.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Cassa di Scura Brillante",s="Sulle fredde alture di Dun Morogh, la Cassa di Scura Brillante è diretta verso le montagne orientali. Rejold Maltorzo ha prodotto la nuova, potente birra, e suo fratello ne manda una botte a est in regalo ad altri montanari nanici.",h="Sulle fredde alture di Dun Morogh, la Cassa di Scura Brillante è diretta verso le montagne orientali.",kw={"cassa di scura brillante","dun morogh","kadrell","loch modan","rejold maltorzo","scura brillante","thelsamar"},ang={["race:Dwarf"]="Per chi appartiene al popolo dei nani, condividere una buona birra tra una pattuglia e l'altra è una tradizione rispettata, che unisce i Montanari sparsi tra le aspre vette di Khaz Modan."},sec={{t="Una consegna alcolica",b="Rejold Maltorzo produce la Scura Brillante a Borgo Luppolo. I clienti del posto e i montanari che sfidano il gelo pungente di Dun Morogh la apprezzano subito. Colpito dalla birra, suo fratello, il Montanaro Maltorzo, ne commissiona una botte per il viaggio attraverso il passo orientale fino a Loch Modan. I nani tengono molto alle bevande forti, per la compagnia e per il calore nel freddo delle montagne. Condividere una birra fresca con i compagni in pattuglia lontana è una tradizione militare."},{t="Un ricostituente nanico",b="Durante il suo turno di guardia a Thelsamar, il Montanaro Kadrell apre la botte e assaggia la birra. La Scura Brillante è all'altezza del suo nome: si dice che un solo sorso alleggerisca le membra e faccia sentire un soldato come se potesse volare. Un esploratore nanico in una lunga e solitaria pattuglia lungo le strade d'alta quota potrebbe gradire una bevanda così corroborante."}},faq={{q="Che cos'è la Scura Brillante?",a="Rejold Maltorzo produce la Scura Brillante sulle fredde alture di Dun Morogh. La sua forza è famosa perché rinvigorisce il corpo e tiene lontano il freddo.",al={"cos'è la scura brillante","storia della scura brillante","chi ha prodotto la scura brillante"}},{q="A chi viene mandata la botte?",a="La botte è destinata al Montanaro Kadrell, una guardia di stanza lungo la strada che attraversa Thelsamar, a Loch Modan.",al={"chi riceve la botte","dove va la botte","destinatario della botte"}},{q="Perché mandare birra attraverso le montagne?",a="I montanari nanici condividono spesso birre eccezionali con i compagni in pattuglia in luoghi lontani. Dopo aver assaggiato la nuova creazione di Rejold Maltorzo, suo fratello vuole che Kadrell la provi.",al={"perché la consegna","perché consegnare birra","perché mandarla a kadrell"}},{q="Che effetto ha la Scura Brillante su chi la beve?",a="La Scura Brillante è sorprendentemente forte. Dopo averla assaggiata, il Montanaro Kadrell dice che gli fa girare la testa, gli alleggerisce le membra e gli dà la sensazione di poter volare.",al={"quanto è forte la scura brillante","effetto della scura brillante"}}},fx={aa5543f0={q="Da dove viene la Cassa di Scura Brillante e chi l'ha prodotta?",a="Questa birra potente è stata prodotta da Rejold Maltorzo a Borgo Luppolo, a Dun Morogh. Suo fratello, il Montanaro Maltorzo, è rimasto così colpito dalla creazione da preparare questa botte per condividerla fuori dalla loro terra, facendola portare da un avventuriero fino a Loch Modan.",al={"chi ha prodotto la scura brillante","da dove viene la scura brillante","birraio della cassa di scura brillante"}},["3b29018e"]={q="Perché qualcuno vuole la Cassa di Scura Brillante?",a="Il Montanaro Maltorzo adora la nuova ricetta del fratello e vuole che un altro uomo di guardia, il Montanaro Kadrell, ne assaggi la produzione. Kadrell pattuglia le strade gelide attorno a Thelsamar, e una robusta birra nanica che scalda il sangue, scioglie le membra e fa girare la testa è un bel conforto durante i lunghi turni di guardia.",al={"perché mandare la scura brillante","chi vuole la cassa di scura brillante","perché kadrell vuole la scura brillante"}}},fp="21,209,19.430.0,20.316.0,22.150.0,30.108.0,34.162.0,51.167.0"}
