P.entries["item:crate-of-crash-helmets"] = {n="Cassa di Elmetti Schiacciati",s="Una pesante spedizione di elmi da Macchina d'Assedio nanici destinata alle Distese Salate, a Millepicchi. Gli elmi robusti servono urgentemente ai fratelli Dadicorti per proteggere i piloti collaudatori dalle commozioni cerebrali causate dalle loro sperimentali auto a razzo.",h="Una pesante spedizione di elmi da Macchina d'Assedio nanici destinata alle Distese Salate, a Millepicchi.",kw={"cassa di elmetti schiacciati","pista dei miraggi","auto a razzo","distese salate","macchina d'assedio","millepicchi","wizzle dadicorti"},ang={["profession:Engineering"]="Ogni ingegnere conosce il delicato equilibrio tra la massima propulsione e il guasto catastrofico, e l'assoluta necessità di una corazza pesante quando la sicurezza è l'ultimo dei pensieri.",["race:Gnome"]="Per gli gnomi della Pista dei Miraggi, le commozioni cerebrali dei piloti sono semplicemente il prezzo da pagare per superare in innovazione i rivali goblin sulle distese saline."},sec={{t="Sicurezza ad alta velocità",b="Nell'abbagliante distesa bianca delle Distese Salate, gli ingegneri gnomi spingono al limite la propulsione meccanica. Purtroppo per i piloti collaudatori, le auto a razzo sperimentali progettate dai fratelli Dadicorti vanno molto più veloci di quanto il loro sterzo possa gestire in modo affidabile. Con i piloti che subiscono di continuo violenti incidenti e traumi alla testa, i normali berretti di cuoio non bastano più. Per evitare che il loro elenco di temerari volontari si esaurisca del tutto, robusti elmi nanici da Macchina d'Assedio vengono imballati e spediti oltre il mare per mantenere i piloti coscienti, e vivi."}},faq={{q="Che cosa contiene la Cassa di Elmetti Schiacciati?",a="La cassa contiene pesanti elmi da Macchina d'Assedio presi dalle scorte militari naniche. Costruiti per resistere a esplosioni violente e a urti violenti tra veicoli, offrono la protezione per la testa più spessa disponibile per le prove ad alta velocità.",al={"contenuto della cassa","che elmi sono","tipo di elmetti"}},{q="Chi ha bisogno di questi elmi?",a="Vengono mandati a Wizzle Dadicorti e a suo fratello alla Pista dei Miraggi, nelle Distese Salate. I loro progetti sconsiderati di veicoli mettono di continuo fuori combattimento i piloti collaudatori, creando un bisogno urgente di una seria protezione per la testa.",al={"chi riceve gli elmi","per chi è la cassa","destinazione degli elmi"}},{q="Perché i fratelli Dadicorti hanno così tanti incidenti?",a="La progettazione gnomica dei veicoli privilegia la velocità pura e il superamento dei limiti tecnologici rispetto alla stabilità di guida. I fratelli hanno costruito un'auto a razzo eccezionalmente veloce, ma la sua velocità rende le collisioni sulle distese saline quasi inevitabili.",al={"perché si schiantano","problemi dell'auto a razzo","incidenti delle corse gnomiche"}},{q="Dove vengono consegnati gli elmi?",a="La spedizione deve essere portata alle Distese Salate, la vasta distesa salina nella parte sud-orientale di Millepicchi, su Kalimdor.",al={"luogo di consegna","dov'è wizzle","dove vanno"}}},fx={["94078cd5"]={q="Da dove viene la Cassa di Elmetti Schiacciati e chi l'ha preparata?",a="La cassa è stata imballata e fornita dall'ingegnere nano Pilota Barbalunga, a Dun Morogh. Barbalunga ha messo insieme una scorta di robusti elmetti nanici da Macchina d'Assedio per aiutare i suoi vecchi amici, i fratelli Dadicorti, che hanno un disperato bisogno di protezioni per la testa dei loro collaudatori nelle Distese Salate.",al={"chi ha preparato la cassa di elmetti schiacciati","da dove viene la cassa di elmetti schiacciati","origine degli elmetti"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="Cassa di Ferri di Cavallo",s="A Elwynn, la Cassa di Ferri di Cavallo porta cinquanta ferri verso Borgolago.",h="A Elwynn, la Cassa di Ferri di Cavallo porta cinquanta ferri verso Borgolago.",kw={"cassa di ferri di cavallo","foresta di elwynn","borgodoro","borgolago","crestarossa","fabbro argus","verner osgood"},ang={["faction:Alliance"]="I corrieri che portano merci tra Elwynn e Crestarossa tengono aperte le fragili rotte commerciali del regno e le guarnigioni periferiche equipaggiate, anche mentre Roccavento nega i rinforzi militari.",["profession:Blacksmithing"]="La consegna mostra la costante richiesta di prodotti di base della forgia lungo le strade di frontiera tra i paesi. Borgolago dipende dall'incudine di Borgodoro per tenere al lavoro i suoi animali da tiro."},sec={{t="Una consegna per Borgolago",b="Il Fabbro Argus ha forgiato cinquanta ferri di cavallo nuovi a Borgodoro, poi li ha imballati in una cassa e l'ha inchiodata. Li ha ordinati Verner Osgood per Borgolago, dove la pressione di gnoll e orchi costringe gli artigiani del posto a dipendere da Elwynn per i beni in metallo essenziali. La consegna soddisfa il disperato bisogno di attrezzatura di Verner, e Argus allega una severa fattura perché l'artigiano di Crestarossa sappia che la sopravvivenza sulla frontiera ha un prezzo salato."}},faq={{q="Che cosa contiene la Cassa di Ferri di Cavallo?",a="Il Fabbro Argus ha forgiato cinquanta ferri di cavallo a Borgodoro e li ha imballati nella cassa. Una fattura allegata chiede il pagamento all'acquirente.",al={"contenuto della cassa","cosa c'è nella cassa","contenuto della cassa di ferri di cavallo"}},{q="Chi ha ordinato questa cassa?",a="I ferri di cavallo li ha commissionati Verner Osgood, un commerciante e artigiano di Borgolago sulle Montagne Crestarossa, che ne ha bisogno per far andare avanti il suo lavoro e gli animali da tiro del posto.",al={"chi vuole i ferri di cavallo","ferri di cavallo di verner","destinatario della cassa"}},{q="Chi ha forgiato questi ferri di cavallo?",a="Il Fabbro Argus, il fabbro di Borgodoro nella Foresta di Elwynn, ha forgiato i ferri, imballato la cassa e l'ha preparata per la consegna.",al={"chi ha fatto i ferri di cavallo","fabbro di borgodoro","fabbro argus"}},{q="Perché Verner ha bisogno di ferri di cavallo da Elwynn?",a="Gli ostili orchi Roccianera e gli gnoll assediano Borgolago, lasciando l'insediamento di frontiera isolato e a corto di materie prime e merci. I lavoratori del posto devono procurarsi le forniture di base da insediamenti più sicuri come Borgodoro.",al={"perché crestarossa ha bisogno di ferri","perché importare ferri di cavallo","problema di rifornimenti di borgolago"}}},fx={["50a21bee"]={q="Che cos'è la Cassa di Ferri di Cavallo?",a="La Cassa di Ferri di Cavallo è una pesante cassa di legno per le consegne, che contiene cinquanta ferri di cavallo appena forgiati, con allegata una nota di fattura. Il Fabbro Argus ha preparato la spedizione a Borgodoro per evadere un ordine di Verner Osgood, che ha un disperato bisogno di ferro nuovo per tenere ferrati gli animali da tiro e le cavalcature nella vicina Borgolago.",al={"che cos'è la cassa di ferri di cavallo","storia della cassa di ferri di cavallo","a cosa servono i ferri di cavallo"}}},fp="19,73,23.425.0,39.132.0,23.179.0,29.124.0,44.219.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Cassa di Scorte della Locanda",s="Nella Valle Crestafredda servono viaggiatori per portare la Cassa di Scorte della Locanda a Kharanos. I trogg hanno chiuso il passo di montagna, e la Distilleria Birratuono dipende dal loro aiuto.",h="Nella Valle Crestafredda servono viaggiatori per portare la Cassa di Scorte della Locanda a Kharanos.",kw={"forgiamara","crestafredda","cassa","gelmartello","hands","kharanos","giraruota","scorte","tannok","trogg"},ang={["race:Dwarf"]="Per chi è giovane nano, portare queste scorte è il primo servizio fuori dalla Valle Crestafredda: sfidi il passo invaso dai trogg per aiutare i tuoi simili a Kharanos.",["race:Gnome"]="Per chi è gnomo appena arrivato, portare il pacco di Hands Giraruota è un modo pratico per guadagnarsi la simpatia dei nani che gestiscono le locande di Dun Morogh."},sec={{t="Attraverso il passo dei trogg",b="Vicino a Forgiamara, la Cassa di Scorte della Locanda attende un passaggio sicuro attraverso il Passo Crestafredda. I trogg hanno interrotto la strada, impedendo ai corrieri civili di portare merci finché i Montanari non l'avranno liberata. Hands Giraruota ha imballato provviste per la taverna destinate a Tannok Gelmartello, a Kharanos, dove servono."}},faq={{q="Che cosa contiene la cassa?",a="La cassa contiene scorte generiche per la taverna della locanda di Kharanos, dove viaggiatori e gente del posto cercano calore.",al={"contenuto della cassa","contenuto delle scorte della locanda","cosa c'è nella scatola"}},{q="Chi manda la cassa a Kharanos?",a="Hands Giraruota imballa la cassa vicino a Forgiamara e chiede ai viaggiatori che lasciano la Valle Crestafredda di portarla oltre il passo di montagna.",al={"chi dà la cassa","hands giraruota","mittente"}},{q="Perché il normale corriere non poteva consegnarla?",a="I trogg hanno invaso il Passo Crestafredda, rendendolo troppo pericoloso per i normali corrieri senza una scorta di Montanari. I viaggiatori capaci di farsi strada combattendo sono la speranza immediata della locanda per ricevere le scorte.",al={"perché hands non può consegnarla","passo bloccato","perché affidarla a un avventuriero"}},{q="Chi riceve le scorte?",a="Il pacco lo riceve Tannok Gelmartello, l'aiutante dell'oste alla Distilleria Birratuono di Kharanos.",al={"chi riceve la cassa","tannok gelmartello","oste di kharanos"}}},fx={bc2f2ebd={q="Che cos'è la Cassa di Scorte della Locanda?",a="È un pacco di merci preparato da Hands Giraruota al Passo Crestafredda e destinato alla Distilleria Birratuono, la locanda di Kharanos. Poiché il passo che esce dalla Valle Crestafredda è stato bloccato dai trogg, la spedizione è rimasta ferma finché qualcuno in forze non ha potuto trasportarla dall'altra parte.",al={"che cos'è la cassa di scorte della locanda","oggetto di missione cassa di scorte della locanda","che cassa è questa"}},e676223e={q="Perché a Kharanos serve la Cassa di Scorte della Locanda?",a="Tannok Gelmartello, aiutante alla locanda di Kharanos, aspetta nuove scorte dalla Valle Crestafredda, mentre le notizie scarseggiano per via della rivolta dei trogg. Con i normali collegamenti dei corrieri interrotti, la locanda ha bisogno che queste provviste passino il valico, per continuare a rifornire viaggiatori e gente del posto accanto al fuoco.",al={"perché tannok vuole la cassa","perché servono le scorte della locanda","scopo della cassa di scorte della locanda"}}},fp="21,187,22.318.0,25.104.0,32.133.0,43.198.0,26.109.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Cassa di Lingotti della Forgia della Luce",s="A Roccavento, la Cassa di Lingotti della Forgia della Luce porta la speranza di Boscovespro contro Morbent Vil.",h="A Roccavento, la Cassa di Lingotti della Forgia della Luce porta la speranza di Boscovespro contro Morbent...",kw={"cassa","distretto dei nani","grimand elmore","lingotti","ferro","forgia della luce","morbent vil","roccavento"},ang={["class:Paladin"]="Questi lingotti rispondono alla Luce Sacra. Le armi forgiate con essi sono una rovina naturale per i negromanti e i loro servi non morti.",["profession:Blacksmithing"]="Lavorare il ferro della Forgia della Luce è un'arte rara: anche Grimand Elmore può passare anni senza toccare il metallo sacro."},sec={{t="Una consegna sacra",b="Il ferro della Forgia della Luce è raro, e il suo metallo consacrato incanala il potere sacro contro le entità oscure. Le protezioni di Morbent Vil respingono l'acciaio comune, quindi Boscovespro conta su questi lingotti contro il negromante. Solo un artigiano che conosca la tempra del metallo e ne rispetti la natura sacra può lavorarlo."},{t="Il fabbro d'armi di Roccavento",b="La cassa è destinata a Grimand Elmore, un abile fabbro d'armi nanico del Distretto dei Nani di Roccavento. Non lavora il ferro della Forgia della Luce da anni, eppure accetta di forgiarlo in un'arma santificata, pensata per spezzare le difese di Morbent Vil e abbatterlo."}},faq={{q="Che cosa contiene questa cassa?",a="La cassa contiene ferro consacrato della Forgia della Luce per un'arma pensata per penetrare le difese magiche di Morbent Vil.",al={"contenuto della cassa","cos'è il ferro della forgia della luce","cosa c'è nella scatola"}},{q="Chi deve ricevere questa cassa?",a="La cassa è destinata a Grimand Elmore, un abile fabbro d'armi nanico del Distretto dei Nani di Roccavento.",al={"a chi porto la cassa","destinatario della cassa","dove va la cassa"}},{q="Perché serve il ferro della Forgia della Luce?",a="Le protezioni di Morbent Vil respingono l'acciaio comune. Il ferro della Forgia della Luce incanala il potere sacro contro le entità oscure.",al={"perché il ferro della forgia della luce","perché non il ferro normale","punto debole di morbent vil"}},{q="Chi ha preparato la cassa?",a="Glorin Frontesalda ha imballato nella cassa il ferro della Forgia della Luce che hai recuperato, perché venga consegnato a Grimand Elmore a Roccavento.",al={"chi ha imballato i lingotti","chi ha dato la cassa"}}},fp="26,89,17.292.0,28.272.1,26.104.0,38.101.0,30.111.0,22.117.0"}
