P.entries["item:crystal-kelp-frond"] = {n="Fronda d'Alga di Cristallo",s="I murloc portano Fronde d'Alga di Cristallo dall'oceano al Lago di Cristallo, nella Foresta di Elwynn. William Pestel, a Borgodoro, le cerca per un liquore dell'invisibilità.",h="I murloc portano Fronde d'Alga di Cristallo dall'oceano al Lago di Cristallo, nella Foresta di Elwynn.",kw={"alga di cristallo","fronda d'alga di cristallo","lago di cristallo","borgodoro","liquore dell'invisibilità","murloc","william pestel"},ang={["profession:Herbalism"]="A differenza delle erbe radicate nel terreno, le Fronde d'Alga di Cristallo crescono nell'acqua e non si trovano nei normali punti di raccolta di Elwynn. Chi pratica l'erbalismo deve strapparle ai murloc del posto, che le conservano."},sec={{t="Un raro reagente acquatico",b="Le Fronde d'Alga di Cristallo provengono dagli oceani salati, ed è strano trovarle nelle acque dolci della Foresta di Elwynn. Lungo le rive del Lago di Cristallo, le tribù di murloc raccolgono e conservano le fronde per motivi tutti loro. Gli alchimisti le apprezzano per il loro strano potere di ingannare la vista. William Pestel, a Borgodoro, le usa come ingrediente principale di un liquore dell'invisibilità pensato per aiutare gli innamorati a sfuggire agli occhi vigili delle famiglie."}},faq={{q="Dove cresce naturalmente l'alga di cristallo?",a="L'alga di cristallo cresce negli oceani salati. Non cresce spontaneamente nei laghi d'acqua dolce, ma i murloc ne raccolgono le talee e le portano in posti come il Lago di Cristallo.",al={"dove cresce l'alga di cristallo","origine dell'alga di cristallo","habitat dell'alga"}},{q="Perché i murloc del Lago di Cristallo hanno alghe oceaniche?",a="Non viene spiegato perché i murloc del Lago di Cristallo abbiano alghe oceaniche. Si dice solo che raccolgono e conservano le fronde per motivi tutti loro.",al={"perché i murloc hanno l'alga","motivo dell'alga dei murloc"}},{q="Chi vuole le Fronde d'Alga di Cristallo a Borgodoro?",a="Le Fronde d'Alga di Cristallo le vuole William Pestel, uno speziale della Locanda del Fiero Leone di Borgodoro. Le usa per preparare un liquore dell'invisibilità per Maybell Maclure, così che possa sgattaiolare via dal vigneto di famiglia per incontrare Tommy Joe Pietradura.",al={"chi ha bisogno dell'alga di cristallo","alga di william pestel"}},{q="Che proprietà ha l'alga di cristallo?",a="Gli alchimisti apprezzano le Fronde d'Alga di Cristallo per la loro capacità di ingannare la vista. William Pestel le usa in un liquore dell'invisibilità pensato per aiutare gli innamorati a passare inosservati.",al={"effetti dell'alga","cosa fa l'alga di cristallo"}}},fx={e295764f={q="Che cos'è una Fronda d'Alga di Cristallo?",a="Una Fronda d'Alga di Cristallo è un rametto tagliato dall'alga di cristallo, una rara pianta acquatica che vive nell'oceano. Pur essendo una vegetazione soprattutto marina, queste fronde vengono a volte raccolte e conservate dai murloc attorno a specchi d'acqua dolce, come il Lago di Cristallo. Gli alchimisti le apprezzano per le loro potenti proprietà traslucide, che si possono sfruttare per preparare pozioni speciali, come il liquore dell'invisibilità.",al={"che cos'è la fronda d'alga di cristallo","informazioni sull'alga di cristallo","che cos'è l'alga di cristallo"}},["8bde59b0"]={q="Perché qualcuno vuole le Fronde d'Alga di Cristallo?",a="William Pestel, l'alchimista di Borgodoro, ha bisogno delle fronde d'alga di cristallo per preparare un potente liquore dell'invisibilità. Intende usare l'intruglio per aiutare la giovane Maybell Maclure a sgattaiolare via inosservata dalla vigna, sorvegliata dalla sua famiglia, e a incontrare in segreto il suo innamorato proibito, Tommy Joe Pietradura.",al={"a chi serve l'alga di cristallo","perché raccogliere le fronde d'alga di cristallo","uso dell'alga di cristallo"}}},fp="18,149,22.420.0,39.169.0,51.136.0,43.232.1,42.162.0"}
