P.entries["item:darkhound-blood"] = {n="Sangue di Segugio Oscuro",s="Nei campi e nelle foreste di Tirisfal, i segugi oscuri contaminati forniscono il Sangue di Segugio Oscuro. La Regia Società degli Speziali lo raccoglie come primo reagente per gli esperimenti volti a creare una nuova piaga letale.",h="Nei campi e nelle foreste di Tirisfal, i segugi oscuri contaminati forniscono il Sangue di Segugio Oscuro.",kw={"la nuova piaga","speziale johaan","brill","segugio oscuro","sangue di segugio oscuro","regia società degli speziali","radure di tirisfal"},ang={["faction:Horde"]="A Brill, la Regia Società degli Speziali porta avanti oscuri esperimenti il cui potenziale tossico pochi, al di fuori della cerchia ristretta dei Reietti, comprendono davvero.",["race:Undead"]="Raccogliere reagenti come il Sangue di Segugio Oscuro è un lavoro essenziale per i Reietti: aiuta Dama Sylvanas e la Regia Società degli Speziali a forgiare la loro arma definitiva contro il Flagello."},sec={{t="Materiale per la Nuova Piaga",b="Agli ordini di Dama Sylvanas Ventolesto, la Regia Società degli Speziali cerca un contagio virulento capace di spazzare via Arthas e il suo Flagello. Lo Speziale Johaan è di stanza a Brill. Ipotizza che le bestie del posto, corrotte da energie oscure e resistenti al decadimento circostante, possiedano proprietà biologiche insolite.\n\nDistillando il sangue dei segugi oscuri selvatici, Johaan spera di scoprire composti capaci di resistere a ceppi necrotici virulenti o di diffonderli."}},faq={{q="A che cosa serve il Sangue di Segugio Oscuro?",a="Lo Speziale Johaan, a Brill, usa il Sangue di Segugio Oscuro come reagente iniziale nelle ricerche della Regia Società degli Speziali per creare una nuova piaga, più letale di qualunque cosa Azeroth abbia mai visto.",al={"uso del sangue di segugio oscuro","perché prendere il sangue di segugio oscuro","scopo del sangue di segugio oscuro"}},{q="Quali creature forniscono questo sangue?",a="Il Sangue di Segugio Oscuro proviene dai segugi oscuri maledetti, famelici e decrepiti che vagano per le Radure di Tirisfal.",al={"dove ottenere il sangue di segugio oscuro","chi lascia cadere il sangue di segugio oscuro","fonte del sangue di segugio oscuro"}},{q="Perché i segugi oscuri sono oggetto delle ricerche sulla piaga?",a="Lo Speziale Johaan ipotizza che il sangue delle bestie abituate alle terre corrotte di Tirisfal possa racchiudere i segreti biologici necessari per sintetizzare un contagio inarrestabile.",al={"perché i segugi oscuri","teoria dello speziale johaan","proprietà del segugio oscuro"}}},fx={db825c3d={q="Che cos'è il Sangue di Segugio Oscuro?",a="Il Sangue di Segugio Oscuro è il fluido vitale contaminato dei feroci segugi oscuri che si aggirano per le Radure di Tirisfal. Deformati dalla magia oscura e dalla non morte che aleggia sulle radure, questi cani sventurati hanno un sangue dalle proprietà uniche e resistenti. Ripugnante e pericoloso per le comuni creature viventi, per alchimisti e ricercatori è un mezzo ideale per gli esperimenti biologici, soprattutto quando si studiano composti virulenti o la resistenza al decadimento necrotico.",al={"che cos'è il sangue di segugio oscuro","storia del sangue di segugio oscuro","spiegazione del sangue di segugio oscuro"}},["93cde5f9"]={q="Da dove viene il Sangue di Segugio Oscuro e chi l'ha prodotto?",a="Questo sangue si ricava in natura dai segugi oscuri maledetti, voraci e decrepiti che battono i boschi infestati e le fattorie in rovina delle Radure di Tirisfal. Non è un preparato artificiale, ma il fluido corporeo di bestie che si sono adattate al morbo che avvelena la regione dalla Terza Guerra, e lo hanno assorbito.",al={"provenienza del sangue di segugio oscuro","da dove viene il sangue di segugio oscuro","chi ha creato il sangue di segugio oscuro"}}},fp="15,200,23.432.0,33.180.0,33.99.0,48.172.0"}
